SELECT d.sales_delivery_detail_id AS "salesDeliveryDetailId", d.sales_delivery_id AS "salesDeliveryId", h.customer_id AS "customerId", h.delivery_no AS "deliveryNo", to_char(h.delivery_dt, 'YYYY-MM-DD') AS "deliveryDt", h.delivery_type AS "deliveryType", d.line_no AS "sourceLineNo", d.revenue_closed_at AS "revenueClosedAt", d.total_amt AS "totalAmt", EXISTS ( SELECT 1 FROM tb_sales_statement_dt sd JOIN tb_sales_statement_hd sh ON sh.sales_statement_id = sd.sales_statement_id AND sh.tenant_id = sd.tenant_id WHERE sd.tenant_id = d.tenant_id AND sd.sales_delivery_detail_id = d.sales_delivery_detail_id AND sh.use_at = 'Y' ) AS "hasActiveStatement" FROM tb_sales_delivery_dt d JOIN tb_sales_delivery_hd h ON h.sales_delivery_id = d.sales_delivery_id AND h.tenant_id = d.tenant_id WHERE d.tenant_id = #{tenantId, jdbcType=BIGINT} AND h.tenant_id = #{tenantId, jdbcType=BIGINT} AND h.use_at = 'Y' AND d.sales_delivery_detail_id IN
#{detailId, jdbcType=BIGINT}
ORDER BY h.customer_id, h.sales_delivery_id, d.line_no FOR UPDATE OF h, d

SELECT EXISTS (SELECT 1 FROM tb_sales_statement_hd
WHERE tenant_id = #{tenantId, jdbcType=BIGINT}
  AND sales_delivery_id = #{salesDeliveryId, jdbcType=BIGINT} AND use_at = 'Y')

SELECT EXISTS (
    SELECT 1
    FROM tb_sales_statement_dt sd
    JOIN tb_sales_statement_hd sh
      ON sh.sales_statement_id = sd.sales_statement_id
     AND sh.tenant_id = sd.tenant_id
    WHERE sd.tenant_id = #{tenantId, jdbcType=BIGINT}
      AND sd.sales_delivery_detail_id = #{salesDeliveryDetailId, jdbcType=BIGINT}
      AND sh.use_at = 'Y'
)

mapper.insert:
INSERT INTO tb_sales_statement_dt ( sales_statement_id, tenant_id, sales_delivery_detail_id, line_no, material_code, material_name, material_spec, unit, delivery_qty, unit_price, supply_amt, vat_amt, total_amt) SELECT #{salesStatementId, jdbcType=BIGINT}, d.tenant_id, d.sales_delivery_detail_id, ROW_NUMBER() OVER (ORDER BY h.delivery_dt, h.sales_delivery_id, d.line_no)::integer, m.material_code, m.material_name, m.material_spec, m.unit, d.delivery_qty, d.unit_price, d.supply_amt, d.vat_amt, d.total_amt FROM tb_sales_delivery_dt d JOIN tb_sales_delivery_hd h ON h.sales_delivery_id = d.sales_delivery_id AND h.tenant_id = d.tenant_id LEFT JOIN tb_material_info m ON m.material_id = d.material_id AND m.tenant_id = d.tenant_id WHERE d.tenant_id = #{tenantId, jdbcType=BIGINT} AND d.sales_delivery_detail_id IN
#{detailId, jdbcType=BIGINT}
AND h.customer_id = #{customerId, jdbcType=BIGINT}

mapper.update:
UPDATE tb_sales_statement_dt
SET sales_delivery_detail_id = NULL
WHERE tenant_id = #{tenantId, jdbcType=BIGINT}
  AND sales_statement_id = #{salesStatementId, jdbcType=BIGINT}
